UPDATE employees SET user_id = #{employeeSetting.applyToUser}, name_kh = #{employeeSetting.nameKh}, name_en = #{employeeSetting.nameEn}, telephone = #{employeeSetting.telephone}, email = #{employeeSetting.email}, address = #{employeeSetting.address}, photo = #{employeeSetting.profilePhoto}, dob = #{employeeSetting.dob}, gender = #{employeeSetting.gender}, id_card = #{employeeSetting.idCard}, about_me = #{employeeSetting.aboutMe}, remark = #{employeeSetting.remark}, reason = #{employeeSetting.reason}, emp_reference = #{employeeSetting.reference}, work_experience = #{employeeSetting.workExperience}, department_id = #{employeeSetting.departmentId}, position_id = #{employeeSetting.positionId}, start_working_date = #{employeeSetting.dateOfWork}, current_salary = #{employeeSetting.currentSalary}, allowance = #{employeeSetting.allowance}, marital_id = #{employeeSetting.maritalId}, paid_by = #{employeeSetting.paidType}, account_number = #{employeeSetting.accountNumber}, account_id = #{employeeSetting.accountId}, is_donated = #{employeeSetting.donate}, is_provident_fund = #{employeeSetting.providenceFund}, is_deposit = #{employeeSetting.deposit}, amount_deposit = #{employeeSetting.cashAmount}, num_month = #{employeeSetting.numOfMonth}, employee_status_id = #{employeeSetting.employeeStatusId}, modified = NOW(), modified_by = #{employeeSetting.modifiedBy} WHERE id = #{employeeSetting.id};
